{"cards": [{"node_code": "N_b7e038cbc02557ca", "definition": "研究制造执行系统（MES）在车间层的功能实现，包括工单全生命周期管理、生产进度跟踪、资源调度及车间现场数据的实时采集与监控。", "boundary": "聚焦于车间执行层面的业务逻辑与数据闭环，涵盖从工单下达、派工、报工到完工确认的流程管理，以及设备、人员、物料等现场数据的实时获取。边界在于关注生产执行过程的数字化映射与管理，不涉及跨部门的企业级数据集成架构（归入企业系统集成）或底层设备控制指令（归入制造自动化与数控）。", "includes": ["MES核心功能模块如工单管理、生产调度、质量追溯及绩效分析", "车间现场数据采集（SCADA/DAQ）与生产状态实时监控", "基于工单的生产过程可视化、异常报警及电子作业指导书（eSOP）"], "excludes": ["ERP层面的财务、采购或销售订单管理", "底层PLC/NC的实时运动控制算法或伺服驱动硬件设计"], "sibling_distinctions": [{"other_code": "N_91b86e79e3f608ef", "rule": "本节点关注车间内部的生产执行流程与现场数据；兄弟节点关注设计、工艺、制造数据在跨系统间的标准化交换与企业级集成。"}, {"other_code": "N_c11a9be084eeb28a", "rule": "本节点关注具体业务场景下的数据应用与流转；兄弟节点关注数据本身的语义定义、模型结构及互操作标准。"}], "cross_boundary_rule": "若研究侧重车间内生产任务的执行逻辑与现场数据闭环，主挂载本节点；若侧重数据如何从设计端传递至制造端或与其他企业系统交互，主挂载“CAD、CAPP、CAM数据贯通与企业系统集成”。"}, {"node_code": "N_91b86e79e3f608ef", "definition": "研究计算机辅助设计（CAD）、工艺规划（CAPP）及制造（CAM）数据在制造全链条中的贯通机制，以及制造系统与ERP、PLM等企业级系统的集成架构。", "boundary": "聚焦于跨系统、跨部门的数据流打通与业务协同，涵盖设计-工艺-制造数据的一致性维护、接口开发及企业级信息架构设计。边界在于关注数据在不同软件系统间的标准化传输、转换与集成逻辑，不涉及车间内部的具体生产执行管理（归入MES）或底层数据语义定义（归入数据模型与互操作）。", "includes": ["CAD/CAPP/CAM数据链贯通、工艺路线数字化及制造特征识别", "MES与ERP、PLM、SCM等企业级系统的接口集成与数据同步", "基于BOM（物料清单）的多层级数据一致性及企业级信息架构设计"], "excludes": ["单一软件系统内部的功能开发或算法优化", "不涉及制造场景的通用企业IT架构或纯软件工程方法"], "sibling_distinctions": [{"other_code": "N_b7e038cbc02557ca", "rule": "本节点关注跨系统的数据集成与架构；兄弟节点关注车间内部的生产执行流程与现场数据管理。"}, {"other_code": "N_c11a9be084eeb28a", "rule": "本节点关注数据在系统间的流动与集成应用；兄弟节点关注数据本身的模型定义、语义标准及互操作协议。"}], "cross_boundary_rule": "若研究侧重设计、工艺、制造数据在多个系统间的流转与集成架构，主挂载本节点；若侧重车间内部工单执行与现场数据采集，主挂载“MES、工单与车间数据”；若侧重数据语义标准定义，主挂载“制造数据模型、主数据与互操作”。"}, {"node_code": "N_c11a9be084eeb28a", "definition": "研究制造领域的数据模型构建、主数据管理策略及系统间互操作标准，旨在实现制造数据的语义统一、标准化交换与高效治理。", "boundary": "聚焦于数据本身的“语言”与“规则”，涵盖制造数据模型（如STEP、ISO 10303）、主数据（物料、设备、工艺参数）的标准化定义、数据治理体系及互操作协议（如OPC UA、MTConnect）。边界在于关注数据语义、结构及交换标准，不涉及具体业务系统的功能实现（如MES工单管理）或跨系统集成架构设计。", "includes": ["制造数据模型标准（如STEP、ISO 10303）及语义网技术在制造中的应用", "主数据管理（MDM）策略、物料/设备/工艺主数据的标准化与治理", "工业互操作标准（如OPC UA、MTConnect、SEMA）及数据交换协议"], "excludes": ["具体MES或ERP系统的功能模块开发", "不涉及制造语义的通用数据库理论或纯网络通信协议研究"], "sibling_distinctions": [{"other_code": "N_b7e038cbc02557ca", "rule": "本节点关注数据标准与模型定义；兄弟节点关注基于这些标准在车间执行层面的具体应用。"}, {"other_code": "N_91b86e79e3f608ef", "rule": "本节点关注数据语义与互操作标准；兄弟节点关注利用这些标准实现跨系统的数据集成与架构设计。"}], "cross_boundary_rule": "若研究侧重数据语义定义、模型标准或互操作协议本身，主挂载本节点；若侧重利用标准实现系统间数据流转或车间业务执行，主挂载相应集成或执行节点。"}]}
